export type Mood = 1 | 2 | 3 | 4 | 5;
export type Color = 'red' | 'orange' | 'amber' | 'green' | 'teal' | 'blue' | 'indigo' | 'violet' | 'pink';

export interface Habit {
  id: string;
  name: string;
  emoji: string;
  color: Color;
  createdAt: number;
}

export interface StreakRecord {
  date: string;
  completed: boolean;
}

export interface MoodRecord {
  id: string;
  date: string;
  mood: Mood;
  note?: string;
  createdAt: number;
}

export interface AppState {
  habits: Habit[];
  moodRecords: MoodRecord[];
  darkMode: boolean;
}

export interface StreakData {
  current: number;
  longest: number;
}

import { openDB, DBSchema, IDBPDatabase } from 'idb';
import type { Habit, StreakRecord, MoodRecord, AppState } from './types';

const DB_NAME = 'rhythm-db';
const DB_VERSION = 1;

interface RhythmDB extends DBSchema {
  habits: {
    key: string;
    value: Habit;
  };
  streaks: {
    key: string;
    value: StreakRecord[];
  };
  moods: {
    key: string;
    value: MoodRecord[];
  };
  appState: {
    key: string;
    value: AppState;
  };
}

class Database {
  private db: IDBPDatabase<RhythmDB> | null = null;

  async init(): Promise<void> {
    if (this.db) return;

    this.db = await openDB<RhythmDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        // Habits store
        if (!db.objectStoreNames.contains('habits')) {
          const habitStore = db.createObjectStore('habits', { keyPath: 'id' });
          habitStore.createIndex('createdAt', 'createdAt');
        }

        // Streaks store
        if (!db.objectStoreNames.contains('streaks')) {
          const streakStore = db.createObjectStore('streaks', { keyPath: 'date' });
          streakStore.createIndex('completed', 'completed');
        }

        // Moods store
        if (!db.objectStoreNames.contains('moods')) {
          const moodStore = db.createObjectStore('moods', { keyPath: 'id' });
          moodStore.createIndex('date', 'date');
        }

        // App state store
        if (!db.objectStoreNames.contains('appState')) {
          db.createObjectStore('appState', { keyPath: 'key' });
        }
      },
    });
  }

  async getHabits(): Promise<Habit[]> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readonly');
    const store = tx.objectStore('habits');
    const habits = await store.getAll();
    return habits.sort((a, b) => b.createdAt - a.createdAt);
  }

  async addHabit(habit: Habit): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readwrite');
    await tx.objectStore('habits').put(habit);
    await tx.done;
  }

  async updateHabit(habit: Habit): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readwrite');
    await tx.objectStore('habits').put(habit);
    await tx.done;
  }

  async deleteHabit(id: string): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readwrite');
    await tx.objectStore('habits').delete(id);
    await tx.done;
  }

  async getStreaks(date: string): Promise<StreakRecord | null> {
    await this.init();
    const tx = this.db!.transaction('streaks', 'readonly');
    const store = tx.objectStore('streaks');
    return await store.get(date);
  }

  async setStreak(streak: StreakRecord): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('streaks', 'readwrite');
    await tx.objectStore('streaks').put(streak);
    await tx.done;
  }

  async getMoodsByDate(date: string): Promise<MoodRecord[]> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readonly');
    const store = tx.objectStore('moods');
    const index = store.index('date');
    const moods = await index.getAll(date);
    return moods.sort((a, b) => b.createdAt - a.createdAt);
  }

  async addMood(mood: MoodRecord): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readwrite');
    await tx.objectStore('moods').put(mood);
    await tx.done;
  }

  async updateMood(mood: MoodRecord): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readwrite');
    await tx.objectStore('moods').put(mood);
    await tx.done;
  }

  async deleteMood(id: string): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readwrite');
    await tx.objectStore('moods').delete(id);
    await tx.done;
  }

  async getAppState(): Promise<AppState | null> {
    await this.init();
    const tx = this.db!.transaction('appState', 'readonly');
    const store = tx.objectStore('appState');
    return await store.get('appState');
  }

  async saveAppState(state: AppState): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('appState', 'readwrite');
    await tx.objectStore('appState').put({ key: 'appState', ...state });
    await tx.done;
  }

  // Utility methods
  async getCompletedHabitsForDate(date: string): Promise<Habit[]> {
    const streak = await this.getStreaks(date);
    if (!streak?.completed) return [];

    const habits = await this.getHabits();
    return habits;
  }

  async getWeeklyData(days: number): Promise<{
    dates: string[];
    completedCounts: number[];
    moods: (Mood | null)[];
  }> {
    const today = new Date();
    const dates: string[] = [];
    const completedCounts: number[] = [];
    const moods: (Mood | null)[] = [];

    for (let i = days - 1; i >= 0; i--) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      const dateStr = date.toISOString().split('T')[0];
      dates.push(dateStr);

      const streak = await this.getStreaks(dateStr);
      completedCounts.push(streak?.completed ? 1 : 0);

      const moodRecords = await this.getMoodsByDate(dateStr);
      moods.push(moodRecords.length > 0 ? moodRecords[0].mood : null);
    }

    return { dates, completedCounts, moods };
  }
}

export const db = new Database();

import { db } from './database';
import type { Habit, StreakData } from './types';

export function calculateStreaks(streaks: { completed: boolean }[]): StreakData {
  let currentStreak = 0;
  let longestStreak = 0;
  let tempStreak = 0;

  // Calculate from most recent to oldest
  for (let i = streaks.length - 1; i >= 0; i--) {
    if (streaks[i].completed) {
      currentStreak++;
      tempStreak++;
      longestStreak = Math.max(longestStreak, tempStreak);
    } else {
      // If we find a non-completed day in the recent streak, reset
      if (i < streaks.length - 1 && streaks[i + 1]?.completed) {
        currentStreak = 0;
      }
      tempStreak = 0;
    }
  }

  return { current: currentStreak, longest: longestStreak };
}

export async function getHabitStreakData(habitId: string): Promise<StreakData> {
  // Get all streak records
  const habits = await db.getHabits();
  const habit = habits.find(h => h.id === habitId);

  if (!habit) {
    return { current: 0, longest: 0 };
  }

  // For now, return generic streak (in real app, track per-habit)
  return { current: 0, longest: 0 };
}

export async function toggleHabit(habitId: string, date: string): Promise<boolean> {
  const existing = await db.getStreaks(date);

  if (existing) {
    // Toggle
    await db.setStreak({ ...existing, completed: !existing.completed });
    return !existing.completed;
  } else {
    // Create new
    await db.setStreak({ date, completed: true });
    return true;
  }
}

export async function getMood(date: string) {
  const moods = await db.getMoodsByDate(date);
  return moods.length > 0 ? moods[0] : null;
}

export async function setMood(mood: number, note?: string): Promise<void> {
  const today = new Date().toISOString().split('T')[0];

  const existing = await getMood(today);
  const moodRecord = {
    id: existing?.id || crypto.randomUUID(),
    date: today,
    mood: mood as 1 | 2 | 3 | 4 | 5,
    note: note,
    createdAt: Date.now(),
  };

  if (existing) {
    await db.updateMood(moodRecord);
  } else {
    await db.addMood(moodRecord);
  }
}

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import { db } from './database';
import type { Habit, AppState } from './types';

interface AppStateContextType {
  habits: Habit[];
  appState: AppState;
  addHabit: (habit: Habit) => void;
  updateHabit: (habit: Habit) => void;
  deleteHabit: (id: string) => void;
  toggleDarkMode: () => void;
}

const AppStateContext = createContext<AppStateContextType | undefined>(undefined);

export function AppStateProvider({ children }: { children: ReactNode }) {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [appState, setAppState] = useState<AppState>({
    habits: [],
    moodRecords: [],
    darkMode: false,
  });

  useEffect(() => {
    loadState();
  }, []);

  async function loadState() {
    const state = await db.getAppState();
    if (state) {
      setAppState(state);
      setHabits(state.habits);
    }
  }

  async function addHabit(habit: Habit) {
    await db.addHabit(habit);
    const newHabits = [...habits, habit];
    setHabits(newHabits);
    await db.saveAppState({ ...appState, habits: newHabits });
  }

  async function updateHabit(updatedHabit: Habit) {
    await db.updateHabit(updatedHabit);
    const newHabits = habits.map(h => h.id === updatedHabit.id ? updatedHabit : h);
    setHabits(newHabits);
    await db.saveAppState({ ...appState, habits: newHabits });
  }

  async function deleteHabit(id: string) {
    await db.deleteHabit(id);
    const newHabits = habits.filter(h => h.id !== id);
    setHabits(newHabits);
    await db.saveAppState({ ...appState, habits: newHabits });
  }

  async function toggleDarkMode() {
    const newDarkMode = !appState.darkMode;
    const newState = { ...appState, darkMode: newDarkMode };
    await db.saveAppState(newState);
    setAppState(newState);
  }

  return (
    <AppStateContext.Provider value={{ habits, appState, addHabit, updateHabit, deleteHabit, toggleDarkMode }}>
      {children}
    </AppStateContext.Provider>
  );
}

export function useAppState() {
  const context = useContext(AppStateContext);
  if (context === undefined) {
    throw new Error('useAppState must be used within an AppStateProvider');
  }
  return context;
}

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatDate(date: Date): string {
  return new Intl.DateTimeFormat('de-DE', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  }).format(date);
}

export function formatShortDate(date: Date): string {
  return new Intl.DateTimeFormat('de-DE', {
    month: 'short',
    day: 'numeric',
  }).format(date);
}

export function getTodayDateString(): string {
  return new Date().toISOString().split('T')[0];
}

export function getColorClasses(color: string): { bg: string; text: string; border: string } {
  const colors: Record<string, { bg: string; text: string; border: string }> = {
    red: { bg: 'bg-red-50', text: 'text-red-600', border: 'border-red-100' },
    orange: { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100' },
    amber: { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-100' },
    green: { bg: 'bg-green-50', text: 'text-green-600', border: 'border-green-100' },
    teal: { bg: 'bg-teal-50', text: 'text-teal-600', border: 'border-teal-100' },
    blue: { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100' },
    indigo: { bg: 'bg-indigo-50', text: 'text-indigo-600', border: 'border-indigo-100' },
    violet: { bg: 'bg-violet-50', text: 'text-violet-600', border: 'border-violet-100' },
    pink: { bg: 'bg-pink-50', text: 'text-pink-600', border: 'border-pink-100' },
  };

  return colors[color] || { bg: 'bg-gray-50', text: 'text-gray-600', border: 'border-gray-100' };
}

export function getMoodEmoji(mood: number): string {
  const moods = ['', '😡', '😟', '😐', '🙂', '🥰'];
  return moods[mood] || '😐';
}

import { ReactNode } from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  icon?: ReactNode;
}

export function Button({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  icon,
  className = '', 
  ...props 
}: ButtonProps) {
  const baseStyles = 'inline-flex items-center justify-center font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed';

  const variants = {
    primary: 'bg-gray-900 text-white hover:bg-gray-800 focus:ring-gray-900 shadow-sm',
    secondary: 'bg-gray-100 text-gray-900 hover:bg-gray-200 focus:ring-gray-200',
    outline: 'border border-gray-300 text-gray-700 hover:bg-gray-50 focus:ring-gray-400 bg-transparent',
    ghost: 'text-gray-600 hover:bg-gray-100 hover:text-gray-900 focus:ring-gray-400 bg-transparent',
  };

  const sizes = {
    sm: 'px-3 py-1.5 text-sm gap-1.5',
    md: 'px-4 py-2 text-base gap-2',
    lg: 'px-6 py-3 text-lg gap-2.5',
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {icon && <span className="shrink-0">{icon}</span>}
      {children}
    </button>
  );
}

import { ReactNode } from 'react';

