import { ReactNode } from 'react';

interface BadgeProps {
  children: ReactNode;
  variant?: 'success' | 'warning' | 'danger' | 'neutral';
  size?: 'sm' | 'md';
}

export function Badge({ children, variant = 'neutral', size = 'md' }: BadgeProps) {
  const variants = {
    success: 'bg-green-50 text-green-700 border-green-100',
    warning: 'bg-amber-50 text-amber-700 border-amber-100',
    danger: 'bg-red-50 text-red-700 border-red-100',
    neutral: 'bg-gray-50 text-gray-600 border-gray-100',
  };

  const sizes = {
    sm: 'px-2 py-1 text-xs font-medium',
    md: 'px-3 py-1.5 text-sm font-medium',
  };

  return (
    <span className={`
      inline-flex items-center
      rounded-full border
      ${variants[variant]} ${sizes[size]}
    `}>
      {children}
    </span>
  );
}

import { ReactNode } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

interface Tab {
  id: string;
  label: string;
  icon: ReactNode;
}

interface TabsProps {
  tabs: Tab[];
  activeTab: string;
  onChange: (tabId: string) => void;
}

export function Tabs({ tabs, activeTab, onChange }: TabsProps) {
  return (
    <div className="flex items-center gap-1 bg-gray-100/50 p-1 rounded-xl">
      {tabs.map((tab) => {
        const isActive = activeTab === tab.id;
        return (
          <button
            key={tab.id}
            onClick={() => onChange(tab.id)}
            className={`
              flex-1 flex flex-col items-center justify-center gap-1
              px-3 py-2.5
              rounded-lg
              transition-all duration-200
              ${isActive 
                ? 'bg-white text-gray-900 shadow-sm' 
                : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200/50'
              }
            `}
          >
            <span className="text-lg">{tab.icon}</span>
            <span className="text-[10px] font-medium tracking-wide">{tab.label}</span>
          </button>
        );
      })}
    </div>
  );
}

import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppStateProvider } from './context';
import { TodayScreen } from './screens/TodayScreen';
import { WeekScreen } from './screens/WeekScreen';
import { SettingsScreen } from './screens/SettingsScreen';
import { Navbar } from './components/Navbar';

export function App() {
  return (
    <AppStateProvider>
      <BrowserRouter>
        <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
          <div className="max-w-lg mx-auto min-h-screen bg-white shadow-xl">
            <Routes>
              <Route path="/" element={<Navigate to="/today" replace />} />
              <Route path="/today" element={
                <>
                  <Navbar activeTab="today" />
                  <TodayScreen />
                </>
              } />
              <Route path="/week" element={
                <>
                  <Navbar activeTab="week" />
                  <WeekScreen />
                </>
              } />
              <Route path="/settings" element={
                <>
                  <Navbar activeTab="settings" />
                  <SettingsScreen />
                </>
              } />
            </Routes>
          </div>
        </div>
      </BrowserRouter>
