export type Mood = 1 | 2 | 3 | 4 | 5;
export type Color = 'red' | 'orange' | 'amber' | 'green' | 'teal' | 'blue' | 'indigo' | 'violet' | 'pink';

export interface Habit {
  id: string;
  name: string;
  emoji: string;
  color: Color;
  createdAt: number;
}

export interface StreakRecord {
  date: string;
  completed: boolean;
}

export interface MoodRecord {
  id: string;
  date: string;
  mood: Mood;
  note?: string;
  createdAt: number;
}

export interface AppState {
  habits: Habit[];
  moodRecords: MoodRecord[];
  darkMode: boolean;
}

import { openDB, DBSchema, IDBPDatabase } from 'idb';
import type { Habit, StreakRecord, MoodRecord, AppState } from './types';

const DB_NAME = 'rhythm-db';
const DB_VERSION = 1;

interface RhythmDB extends DBSchema {
  habits: {
    key: string;
    value: Habit;
  };
  streaks: {
    key: string;
    value: StreakRecord;
  };
  moods: {
    key: string;
    value: MoodRecord;
  };
  appState: {
    key: string;
    value: AppState;
  };
}

class Database {
  private db: IDBPDatabase<RhythmDB> | null = null;

  async init(): Promise<void> {
    if (this.db) return;

    this.db = await openDB<RhythmDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        // Habits store
        if (!db.objectStoreNames.contains('habits')) {
          db.createObjectStore('habits', { keyPath: 'id' });
        }

        // Streaks store
        if (!db.objectStoreNames.contains('streaks')) {
          db.createObjectStore('streaks', { keyPath: 'date' });
        }

        // Moods store
        if (!db.objectStoreNames.contains('moods')) {
          db.createObjectStore('moods', { keyPath: 'id' });
        }

        // App state store
        if (!db.objectStoreNames.contains('appState')) {
          db.createObjectStore('appState', { keyPath: 'key' });
        }
      },
    });
  }

  async getHabits(): Promise<Habit[]> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readonly');
    const store = tx.objectStore('habits');
    const habits = await store.getAll();
    return habits.sort((a, b) => b.createdAt - a.createdAt);
  }

  async addHabit(habit: Habit): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readwrite');
    await tx.objectStore('habits').put(habit);
    await tx.done;
  }

  async updateHabit(habit: Habit): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readwrite');
    await tx.objectStore('habits').put(habit);
    await tx.done;
  }

  async deleteHabit(id: string): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('habits', 'readwrite');
    await tx.objectStore('habits').delete(id);
    await tx.done;
  }

  async getStreaks(date: string): Promise<StreakRecord | null> {
    await this.init();
    const tx = this.db!.transaction('streaks', 'readonly');
    const store = tx.objectStore('streaks');
    return await store.get(date) ?? null;
  }

  async setStreak(streak: StreakRecord): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('streaks', 'readwrite');
    await tx.objectStore('streaks').put(streak);
    await tx.done;
  }

  async getMoodsByDate(date: string): Promise<MoodRecord[]> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readonly');
    const store = tx.objectStore('moods');
    const index = store.index('date');
    const moods = await index.getAll(date);
    return moods.sort((a, b) => b.createdAt - a.createdAt);
  }

  async addMood(mood: MoodRecord): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readwrite');
    await tx.objectStore('moods').put(mood);
    await tx.done;
  }

  async updateMood(mood: MoodRecord): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readwrite');
    await tx.objectStore('moods').put(mood);
    await tx.done;
  }

  async deleteMood(id: string): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('moods', 'readwrite');
    await tx.objectStore('moods').delete(id);
    await tx.done;
  }

  async getAppState(): Promise<AppState | null> {
    await this.init();
    const tx = this.db!.transaction('appState', 'readonly');
    const store = tx.objectStore('appState');
    return await store.get('appState') ?? null;
  }

  async saveAppState(state: AppState): Promise<void> {
    await this.init();
    const tx = this.db!.transaction('appState', 'readwrite');
    await tx.objectStore('appState').put({ key: 'appState', ...state });
    await tx.done;
  }

  // Utility methods
  async getCompletedHabitsForDate(date: string): Promise<Habit[]> {
    const streak = await this.getStreaks(date);
    if (!streak?.completed) return [];

    const habits = await this.getHabits();
    return habits;
  }

  async getWeeklyData(days: number): Promise<{
    dates: string[];
    completedCounts: number[];
    moods: (Mood | null)[];
  }> {
    const today = new Date();
    const dates: string[] = [];
    const completedCounts: number[] = [];
    const moods: (Mood | null)[] = [];

    for (let i = days - 1; i >= 0; i--) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      const dateStr = date.toISOString().split('T')[0];
      dates.push(dateStr);

      const streak = await this.getStreaks(dateStr);
      completedCounts.push(streak?.completed ? 1 : 0);

      const moodRecords = await this.getMoodsByDate(dateStr);
      moods.push(moodRecords.length > 0 ? moodRecords[0].mood : null);
    }

    return { dates, completedCounts, moods };
  }
}

export const db = new Database();

import { db } from './database';
import type { StreakData, Mood } from './types';

export function calculateStreaks(streaks: { completed: boolean }[]): StreakData {
  let currentStreak = 0;
  let longestStreak = 0;
  let tempStreak = 0;

  for (let i = streaks.length - 1; i >= 0; i--) {
    if (streaks[i].completed) {
      currentStreak++;
      tempStreak++;
      longestStreak = Math.max(longestStreak, tempStreak);
    } else {
      if (i < streaks.length - 1 && streaks[i + 1]?.completed) {
        currentStreak = 0;
      }
      tempStreak = 0;
    }
  }

  return { current: currentStreak, longest: longestStreak };
}

export async function getHabitStreakData(): Promise<StreakData> {
  return { current: 0, longest: 0 };
}

export async function toggleHabit(date: string): Promise<boolean> {
  const existing = await db.getStreaks(date);

  if (existing) {
    await db.setStreak({ ...existing, completed: !existing.completed });
    return !existing.completed;
  } else {
    await db.setStreak({ date, completed: true });
    return true;
  }
}

export async function getMood(date: string) {
  const moods = await db.getMoodsByDate(date);
  return moods.length > 0 ? moods[0] : null;
}

export async function setMood(mood: Mood, note?: string): Promise<void> {
  const today = new Date().toISOString().split('T')[0];

  const existing = await getMood(today);
  const moodRecord = {
    id: existing?.id || crypto.randomUUID(),
    date: today,
    mood,
    note,
    createdAt: Date.now(),
  };

  if (existing) {
    await db.updateMood(moodRecord);
  } else {
    await db.addMood(moodRecord);
  }
}

export interface StreakData {
  current: number;
  longest: number;
}

import { useState, useEffect } from 'react';
import { useAppState } from '../context';
import { db } from '../database';
import { Button } from '../components/ui/Button';
import { Badge } from '../components/ui/Badge';
import { formatDate, getTodayDateString, getColorClasses } from '../lib/utils';
import { HabitManager } from '../components/HabitManager';
import { Plus } from 'lucide-react';

export function TodayScreen() {
  const { habits } = useAppState();
  const [completedCount, setCompletedCount] = useState(0);
  const [isHabitAnimating, setIsHabitAnimating] = useState<string | null>(null);
  const [streak, setStreak] = useState<{ completed: boolean } | null>(null);

  useEffect(() => {
    checkCompletedHabits();
  }, [habits]);

  async function checkCompletedHabits() {
    const today = getTodayDateString();
    const storedStreak = await db.getStreaks(today);
    setStreak(storedStreak);

    if (storedStreak?.completed) {
      setCompletedCount(habits.length);
    } else {
      setCompletedCount(0);
    }
  }

  async function toggleHabit(habitId: string) {
    setIsHabitAnimating(habitId);

    const today = getTodayDateString();
    const existing = await db.getStreaks(today);

    let newCompletedCount = completedCount;

    if (existing && existing.completed) {
      await db.setStreak({ ...existing, completed: false });
      newCompletedCount = Math.max(0, completedCount - 1);
    } else {
      await db.setStreak({ date: today, completed: true });
      newCompletedCount = habits.length;
    }

    setCompletedCount(newCompletedCount);
    const newStreak = { completed: newCompletedCount === habits.length && habits.length > 0 };
    setStreak(newStreak);
    setTimeout(() => setIsHabitAnimating(null), 300);
  }

  return (
    <div className="p-4 space-y-6 pb-24 animate-in fade-in duration-500">
      {/* Header */}
      <div className="text-center space-y-2">
        <p className="text-gray-500 text-sm font-medium">
          {formatDate(new Date())}
        </p>
        <h1 className="text-4xl font-bold text-gray-900 tracking-tight">
          Guten Tag!
        </h1>
        <div className="flex items-center justify-center gap-3">
          <span className="text-2xl font-semibold text-gray-900">
            {completedCount}
          </span>
          <span className="text-gray-500">von {habits.length} erledigt</span>
        </div>
        <div className="w-full bg-gray-100 h-2 rounded-full overflow-hidden">
          <div 
            className="bg-gray-900 h-full transition-all duration-500 ease-out"
            style={{ width: `${habits.length > 0 ? (completedCount / habits.length) * 100 : 0}%` }}
          />
        </div>
      </div>

      {/* Habits List */}
      <div className="space-y-4">
        {habits.length === 0 ? (
          <HabitManager />
        ) : (
          habits.map((habit) => {
            const colorClasses = getColorClasses(habit.color);
            const isCompleted = streak?.completed && habits.length > 0;

            return (
              <Card
                key={habit.id}
                onClick={() => toggleHabit(habit.id)}
                className={`
                  group
                  ${isHabitAnimating === habit.id ? 'scale-[0.98] active:scale-95' : ''}
                  ${isCompleted ? 'bg-gray-50' : ''}
                `}
              >
                <div className="p-4">
                  <div className="flex items-center gap-4">
                    <div className={`
                      w-12 h-12 rounded-2xl flex items-center justify-center text-2xl
                      ${colorClasses.bg} ${colorClasses.text}
                    `}>
                      {habit.emoji}
                    </div>
                    <div className="flex-1">
                      <h3 className="font-semibold text-gray-900 group-hover:text-gray-700 transition-colors">
                        {habit.name}
                      </h3>
                      <div className="flex items-center gap-2 mt-1">
                        <Badge variant="neutral" size="sm">
                          {streak?.completed ? '🔥' : '•'}
                        </Badge>
                      </div>
                    </div>
                    <div className={`
                      w-6 h-6 rounded-full border-2 flex items-center justify-center
                      ${isCompleted 
                        ? 'bg-gray-900 border-gray-900' 
                        : 'border-gray-300 bg-white'
                      }
                      transition-all duration-200
                    `}>
                      {isCompleted && (
                        <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                        </svg>
                      )}
                    </div>
                  </div>
                </div>
              </Card>
            );
